CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, password_hash text NOT NULL, platform_admin boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS institutions (id uuid PRIMARY KEY, name text NOT NULL, city text NOT NULL DEFAULT '', state text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'implantacao' CHECK(status IN ('implantacao','ativa','arquivada')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (user_id uuid NOT NULL REFERENCES users(id), institution_id uuid NOT NULL REFERENCES institutions(id), role text NOT NULL CHECK(role IN ('gestor','diretor','especialista','rh','acolhimento')), PRIMARY KEY(user_id,institution_id));
CREATE TABLE IF NOT EXISTS units (id uuid PRIMARY KEY, institution_id uuid NOT NULL REFERENCES institutions(id), name text NOT NULL, archived_at timestamptz, UNIQUE(id,institution_id));
CREATE TABLE IF NOT EXISTS onboarding_projects (id uuid PRIMARY KEY, institution_id uuid UNIQUE NOT NULL REFERENCES institutions(id), starts_on date NOT NULL, ends_on date NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks (id uuid PRIMARY KEY, institution_id uuid NOT NULL REFERENCES institutions(id), title text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','em_andamento','em_validacao','concluida')), priority text NOT NULL CHECK(priority IN ('baixa','media','alta')), due_on date NOT NULL, owner_name text NOT NULL DEFAULT '', completion_note text, onboarding boolean NOT NULL DEFAULT false, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tasks_tenant_due ON tasks(institution_id,due_on) WHERE archived_at IS NULL;
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY, institution_id uuid REFERENCES institutions(id), actor_id uuid NOT NULL REFERENCES users(id), action text NOT NULL, entity_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_tenant ON audit_logs(institution_id,created_at);
CREATE TABLE IF NOT EXISTS login_attempts (key_hash text PRIMARY KEY, attempts integer NOT NULL, resets_at timestamptz NOT NULL);
